"use client";

import { useState, type FormEvent } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

const TIPOS_IMOVEL = ["Apartamento", "Casa", "Cobertura", "Sala Comercial", "Loja", "Terreno"];

interface AnaliseVendas {
  amostra: number;
  precoM2Mediana: number;
  nivelFiltro: string;
  precoJustoEstimado: number;
}

interface Comparavel {
  id: string;
  titulo: string;
  quartos: number | null;
  mobiliado: boolean | null;
  areaM2: number;
  preco: number;
  url: string;
}

interface AnaliseOfertas {
  amostra: number;
  precoM2Mediana: number;
  nivelFiltro: string;
  precoOfertadoEstimado: number;
  comparaveis: Comparavel[];
}

interface ResultadoPrecificacao {
  vendas: AnaliseVendas | null;
  ofertas: AnaliseOfertas | null;
  indiceDesvio: number | null;
  classificacao: "abaixo_do_mercado" | "dentro_do_mercado" | "acima_do_mercado" | null;
  avisos: string[];
}

const formatadorMoeda = new Intl.NumberFormat("pt-BR", {
  style: "currency",
  currency: "BRL",
  maximumFractionDigits: 0,
});

const ROTULO_CLASSIFICACAO: Record<string, { texto: string; variant: "default" | "secondary" | "destructive" }> = {
  abaixo_do_mercado: { texto: "Abaixo do mercado", variant: "secondary" },
  dentro_do_mercado: { texto: "Dentro do mercado", variant: "default" },
  acima_do_mercado: { texto: "Acima do mercado", variant: "destructive" },
};

export default function Home() {
  const [cidade, setCidade] = useState("Porto Alegre");
  const [bairro, setBairro] = useState("");
  const [tipo, setTipo] = useState("Apartamento");
  const [areaM2, setAreaM2] = useState("");
  const [quartos, setQuartos] = useState("");
  const [mobiliado, setMobiliado] = useState(false);

  const [carregando, setCarregando] = useState(false);
  const [erro, setErro] = useState<string | null>(null);
  const [resultado, setResultado] = useState<ResultadoPrecificacao | null>(null);

  async function aoEnviar(evento: FormEvent<HTMLFormElement>) {
    evento.preventDefault();
    setCarregando(true);
    setErro(null);
    setResultado(null);

    try {
      const resposta = await fetch("/api/precificacao", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          cidade,
          bairro,
          tipo,
          areaM2: Number(areaM2),
          quartos: Number(quartos),
          mobiliado,
        }),
      });

      const dados = await resposta.json();

      if (!resposta.ok) {
        setErro(dados.erro ?? "Não foi possível calcular a precificação.");
        return;
      }

      setResultado(dados);
    } catch {
      setErro("Falha ao conectar com o serviço de precificação.");
    } finally {
      setCarregando(false);
    }
  }

  const classificacao = resultado?.classificacao ? ROTULO_CLASSIFICACAO[resultado.classificacao] : null;

  return (
    <main className="mx-auto flex w-full max-w-2xl flex-1 flex-col gap-6 px-4 py-10">
      <div>
        <h1 className="text-2xl font-semibold tracking-tight">PrecificaJusta</h1>
        <p className="text-sm text-muted-foreground">
          Informe os dados do imóvel para comparar o preço justo (transações reais do ITBI) com o que está sendo
          ofertado no mercado.
        </p>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Dados do imóvel</CardTitle>
          <CardDescription>Cobertura atual: Porto Alegre (ITBI + ofertas Jetlar).</CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={aoEnviar} className="flex flex-col gap-4">
            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-1.5">
                <Label htmlFor="cidade">Cidade</Label>
                <Input id="cidade" value={cidade} onChange={(e) => setCidade(e.target.value)} required />
              </div>
              <div className="flex flex-col gap-1.5">
                <Label htmlFor="bairro">Bairro</Label>
                <Input
                  id="bairro"
                  placeholder="ex: Petrópolis"
                  value={bairro}
                  onChange={(e) => setBairro(e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-1.5">
                <Label htmlFor="tipo">Tipo do imóvel</Label>
                <Select value={tipo} onValueChange={setTipo}>
                  <SelectTrigger id="tipo" className="w-full">
                    <SelectValue placeholder="Selecione" />
                  </SelectTrigger>
                  <SelectContent>
                    {TIPOS_IMOVEL.map((opcao) => (
                      <SelectItem key={opcao} value={opcao}>
                        {opcao}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="flex flex-col gap-1.5">
                <Label htmlFor="areaM2">Área (m²)</Label>
                <Input
                  id="areaM2"
                  type="number"
                  min={1}
                  step="0.01"
                  value={areaM2}
                  onChange={(e) => setAreaM2(e.target.value)}
                  required
                />
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="flex flex-col gap-1.5">
                <Label htmlFor="quartos">Quartos</Label>
                <Input
                  id="quartos"
                  type="number"
                  min={0}
                  step="1"
                  value={quartos}
                  onChange={(e) => setQuartos(e.target.value)}
                  required
                />
              </div>
              <div className="flex flex-col gap-1.5">
                <Label htmlFor="mobiliado">Mobiliado</Label>
                <div className="flex h-8 items-center">
                  <Switch id="mobiliado" checked={mobiliado} onCheckedChange={setMobiliado} />
                </div>
              </div>
            </div>

            <Button type="submit" disabled={carregando} className="mt-2">
              {carregando ? "Calculando..." : "Calcular preço justo"}
            </Button>
          </form>
        </CardContent>
      </Card>

      {erro && (
        <Card className="border-destructive/50">
          <CardContent className="pt-6 text-sm text-destructive">{erro}</CardContent>
        </Card>
      )}

      {resultado && (
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between gap-2">
              <CardTitle>Resultado</CardTitle>
              {classificacao && <Badge variant={classificacao.variant}>{classificacao.texto}</Badge>}
            </div>
            {resultado.indiceDesvio !== null && (
              <CardDescription>
                Índice de desvio: {(resultado.indiceDesvio * 100).toFixed(1)}% em relação ao preço justo estimado.
              </CardDescription>
            )}
          </CardHeader>
          <CardContent className="flex flex-col gap-6">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <p className="text-xs text-muted-foreground">Preço justo estimado (ITBI)</p>
                <p className="text-lg font-semibold">
                  {resultado.vendas ? formatadorMoeda.format(resultado.vendas.precoJustoEstimado) : "—"}
                </p>
                {resultado.vendas && (
                  <p className="text-xs text-muted-foreground">
                    {resultado.vendas.amostra} vendas reais · filtro: {resultado.vendas.nivelFiltro}
                  </p>
                )}
              </div>
              <div>
                <p className="text-xs text-muted-foreground">Preço ofertado no mercado (Jetlar)</p>
                <p className="text-lg font-semibold">
                  {resultado.ofertas ? formatadorMoeda.format(resultado.ofertas.precoOfertadoEstimado) : "—"}
                </p>
                {resultado.ofertas && (
                  <p className="text-xs text-muted-foreground">
                    {resultado.ofertas.amostra} ofertas · filtro: {resultado.ofertas.nivelFiltro}
                  </p>
                )}
              </div>
            </div>

            {resultado.avisos.length > 0 && (
              <div className="rounded-md bg-muted p-3 text-xs text-muted-foreground">
                <ul className="list-inside list-disc">
                  {resultado.avisos.map((aviso) => (
                    <li key={aviso}>{aviso}</li>
                  ))}
                </ul>
              </div>
            )}

            {resultado.ofertas && resultado.ofertas.comparaveis.length > 0 && (
              <div>
                <p className="mb-2 text-xs font-medium text-muted-foreground">Comparáveis usados</p>
                <ul className="flex flex-col gap-2">
                  {resultado.ofertas.comparaveis.map((comparavel) => (
                    <li key={comparavel.id} className="rounded-md border border-border p-3 text-sm">
                      <a href={comparavel.url} target="_blank" rel="noopener noreferrer" className="hover:underline">
                        {comparavel.titulo}
                      </a>
                      <p className="text-xs text-muted-foreground">
                        {comparavel.areaM2}m² · {formatadorMoeda.format(comparavel.preco)}
                        {comparavel.mobiliado ? " · mobiliado" : ""}
                      </p>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </CardContent>
        </Card>
      )}
    </main>
  );
}
